WITH base_data AS (
    SELECT
        up_id,
        uname,
        same_tid_up_concat_value
    FROM b_ads.ads_prty_creator_semi_up_coincide_1d_d
    WHERE log_date = b_current_datedelta('-1')
      AND up_id IN (25826983, 3546780383841185, 318616943, 326505624, 22225638, 207614242, 3707006338730351, 546812289, 519426730, 3707000636573792, 3546932565772301, 1011184180, 3546899774704184, 1294236580, 3546604889967195, 281260033, 21868465, 3706979337898267, 6326024, 3493297234381684, 228889896, 127053639, 2382179, 3706946676852948, 3706983553174277, 472295252, 3706970529859949, 378343641, 3706927630519041, 3690992089697134, 526947724, 37619269, 7407749, 194084427, 3706953280784485, 335119378, 3546737188800991, 3706994127014652, 3493282921319212, 486279256, 102067928, 363430107, 3707007888526060, 2100667986, 3706983829997570, 1675845738, 3546816402426548, 3707005468412608, 542393138, 3707009826293890, 3546640566717099, 3706971400178107, 37275163, 3493295955118296, 142196688, 76783215, 478743761, 573560625, 1412589104, 386098444, 186694825, 287479845, 249219053, 3706975999232556, 591124233, 3546700016781995, 1649090858, 1836958563, 3706997555857654, 3707002748405976, 260490170, 3706952221723306, 10118928, 98694368, 3493282287978675, 3546647986440444, 13643824, 179359653, 3546919982860697, 1494516166, 3546866989926822, 7261647, 1590468496, 381963274, 351303026, 474335046, 3546894615710330, 3706993745333145, 574538816, 3690980393879616, 3707003715193576, 3706940161002422, 1668734897, 692836606, 312538233, 534902534, 282078973, 3546957196823339, 3706966576728538, 3493126043863732, 3707001890670701, 589701831, 3546592848120041, 3706952467089526, 522308449, 15598899, 3706984228456675, 382135084, 8844191, 57919293, 373151972, 302329373, 1840842489, 3706986235431852, 1581346401, 1680511352, 543956072, 3706941532539745, 1478374454, 1147846345, 236609963, 613689140, 3706977981041614, 3706942044244320, 506562675, 273822340, 1934944069, 3706984956168420, 546630884, 3706984505280975, 471946830, 2073106133, 521843274, 47441, 453553505, 140053690, 3546735328627255, 549716427, 2664533, 8320487, 3706961040247654, 3461577239956424, 3546947503786620, 426732823, 3546854486706668, 19418943, 3493289256815316, 3546380817664524, 1116632922, 346425855, 49674352, 3493269549877595, 3493128715635637, 2048309044, 3706943889738311, 3706934404320140, 3706995691489583, 473180623, 3706953125595561, 3706977681148651, 1442663358, 500070540, 3706948790782565, 3706971427440812, 3706996807174676, 3706998310832668, 3706952269957682, 243814348, 3706944500009908, 19435556, 3706950692899600, 1052211360, 3546848144918656, 3546871423306079, 505495625, 514793040, 3493258367862925, 1065941872, 3546822368823787, 3546926968473608, 3546795351214676, 1632914975)
      AND user_type = 'fans'
),
top3_ups AS (
    SELECT
        up_id,
        uname,
        similar_up_id,
        fans_overlap,
        rn
    FROM (
        SELECT
            up_id,
            uname,
            CAST(key AS BIGINT) AS similar_up_id,
            value AS fans_overlap,
            ROW_NUMBER() OVER(PARTITION BY up_id ORDER BY value DESC) AS rn
        FROM base_data
        LATERAL VIEW EXPLODE(same_tid_up_concat_value) t AS key, value
    ) tmp
    WHERE rn <= 3
),
up_names AS (
    SELECT DISTINCT
        up_id,
        nickname
    FROM b_ads.ads_prism_up_query_detail_1d_d
    WHERE log_date = b_current_datedelta('-1')
      AND up_id IN (SELECT similar_up_id FROM top3_ups)
)
SELECT
    t.up_id AS `UP主ID`,
    t.uname AS `UP主昵称`,
    MAP_FROM_ENTRIES(
        COLLECT_LIST(
            STRUCT(CAST(t.similar_up_id AS STRING), t.fans_overlap)
        )
    ) AS `Top3共粉UP共粉数`,
    ARRAY_JOIN(
        COLLECT_LIST(u.nickname),
        ','
    ) AS `Top3共粉UP昵称`
FROM top3_ups t
LEFT JOIN up_names u ON t.similar_up_id = u.up_id
GROUP BY t.up_id, t.uname
ORDER BY t.up_id